{"settings":"{
    "workbench.editorAssociations": {
        "*.ipynb": "jupyter-notebook"
    },
    "[cpp]": {
        "editor.defaultFormatter": "ms-vscode.cpptools"
    },
    "clang-format.assumeFilename": "oogle",
    "editor.rulers": [
        80
    ],
    "editor.cursorStyle": "block",
    "diffEditor.ignoreTrimWhitespace": false,
    "notebook.cellToolbarLocation": {
        "default": "right",
        "jupyter-notebook": "left"
    },
    "editor.suggestSelection": "first",
    "vsintellicode.modify.editor.suggestSelection": "automaticallyOverrodeDefaultValue",
    "peacock.favoriteColors": [
        {
            "name": "Angular Red",
            "value": "#dd0531"
        },
        {
            "name": "Azure Blue",
            "value": "#007fff"
        },
        {
            "name": "JavaScript Yellow",
            "value": "#f9e64f"
        },
        {
            "name": "Mandalorian Blue",
            "value": "#1857a4"
        },
        {
            "name": "Node Green",
            "value": "#215732"
        },
        {
            "name": "React Blue",
            "value": "#61dafb"
        },
        {
            "name": "Something Different",
            "value": "#832561"
        },
        {
            "name": "Svelte Orange",
            "value": "#ff3d00"
        },
        {
            "name": "Vue Green",
            "value": "#42b883"
        }
    ],
    "debug.onTaskErrors": "debugAnyway",
    "C_Cpp.updateChannel": "Insiders",
    "bracketPairColorizer.depreciation-notice": false,
    "chat.agent.enabled": true,
    "workbench.localHistory.maxFileEntries": 10,
    "editor.accessibilitySupport": "on",
    "[python]": {
        "editor.formatOnType": true,
        "editor.defaultFormatter": "ms-python.autopep8"
    },
    "liveshare.accessibility.soundsEnabled": false,
    "github.copilot.editor.enableAutoCompletions": true,
    "cmake.pinnedCommands": [
        "workbench.action.tasks.configureTaskRunner",
        "workbench.action.tasks.runTask"
    ],
    "accessibility.signalOptions.volume": 0,
    "C_Cpp.clang_format_style": "{ BasedOnStyle: LLVM, UseTab: Never, IndentWidth: 4, TabWidth: 4, BreakBeforeBraces: Attach, AllowShortIfStatementsOnASingleLine: false, IndentCaseLabels: false, ColumnLimit: 140, AccessModifierOffset: -4, NamespaceIndentation: All, FixNamespaceComments: false }",
    "workbench.iconTheme": "material-icon-theme",
    "C_Cpp.clang_format_fallbackStyle": "",

        "todohighlight.isEnable": true,
        "todohighlight.isCaseSensitive": true,
        "todohighlight.keywords": [
            "DEBUG:",
            "For DEBUG",
            "REVIEW:",
            {
                "text": "NOTE:",
                "color": "#ff0000",
                "backgroundColor": "orange",
                "overviewRulerColor": "grey"
            },
            {
                "text": "HACK:",
                "color": "#000",
                "isWholeLine": false,
            },
            {
                "text": "FIXME:",
                "color": "#000",
                "isWholeLine": false,
            },
            // {
            //     "text": "TODO:",
            //     "color": "red",
            //     "border": "1px solid red",
            //     "borderRadius": "2px", //NOTE: using borderRadius along with `border` or you will see nothing change
            //     "backgroundColor": "rgba(0,0,0,.2)",
            //     //other styling properties goes here ... 
            // }
        ],

        // "todohighlight.defaultStyle": {
        //     "color": "red",
        //     "backgroundColor": "#ffab00",
        //     "overviewRulerColor": "#ffab00",
        //     "cursor": "pointer",
        //     "border": "1px solid #eee",
        //     "borderRadius": "2px",
        //     "isWholeLine": true,     //other styling properties goes here ... 
        // },
        "todohighlight.include": [
            "**/*.js",
            "**/*.jsx",
            "**/*.ts",
            "**/*.tsx",
            "**/*.html",
            "**/*.php",
            "**/*.css",
            "**/*.scss"
        ],
        "todohighlight.exclude": [
            "**/node_modules/**",
            "**/bower_components/**",
            "**/dist/**",
            "**/build/**",
            "**/.vscode/**",
            "**/.github/**",
            "**/_output/**",
            "**/*.min.*",
            "**/*.map",
            "**/.next/**"
        ],
    "todohighlight.maxFilesForSearch": 5120,
    "todohighlight.toggleURI": false,
    "github.copilot.nextEditSuggestions.enabled": true,

    // "workbench.colorCustomizations": {
    //     "editor.lineHighlightBorder": "#90a4ae", // Subtle bluish-gray line (used in many themes)
    //     "editor.lineHighlightBackground": "#00000000" // Transparent background
    // }
}"}
